  'A market is where the work happens: its own briefs, its own challenges, its own rooms. Everything social stays worldwide, so joining one never cuts you off from anybody.': 'În piață se întâmplă munca: briefuri proprii, challenge-uri proprii, camere proprii. Tot ce ține de socializare rămâne global, așa că intrarea într-o piață nu te rupe niciodată de nimeni.',
  'A media kit you can send to a brand, share as a link, or download as a PDF. Every word on it is yours to change.': 'Un media kit pe care îl poți trimite unui brand, partaja ca link sau descărca în PDF. Fiecare cuvânt din el îți aparține și îl poți schimba.',
  'A message is how most things here actually start: a meet-up, a collab, a question about a brief.': 'Aici aproape totul începe cu un mesaj: o întâlnire, o colaborare, o întrebare despre un brief.',
  'A milestone pays a VIP once, the month they reach it. Fill in as many rows as you like; each becomes its own bonus you can change later.': 'Un reper se plătește o singură dată fiecărui VIP, în luna în care îl atinge. Completează câte rânduri vrei; fiecare devine un bonus pe care îl poți modifica mai târziu.',
  'A new best month': 'O nouă cea mai bună lună',
  'A new country or region with its own rooms, challenges, leads and members. Creators living there can join it.': 'O țară sau regiune nouă, cu propriile camere, provocări, coordonatori și membri. Creatorii care locuiesc acolo se pot alătura.',
  'A new VIP, day one': 'Un VIP nou, prima zi',
  'A new VIP\'s first day in {m}': 'Prima zi a unui VIP nou în {m}',
  'A note for you. Applicants never see it - it is suggested when you approve them, and you can change it then.': 'O notă pentru tine. Aplicanții nu o văd niciodată – se sugerează când îi aprobi și o poți schimba atunci.',
  'A nudge before a live challenge closes, so you can get your entries in.': 'Un semnal înainte ca un challenge activ să se închidă, ca să apuci să îți trimiți participările.',
  'A number': 'Un număr',
  'A one-off for reaching a total, such as 1M views': 'O plată unică pentru atingerea unui total, precum 1 M de vizualizări',
  'A past admin': 'Un fost administrator',
  'A percentage': 'Un procent',
  'a photo': 'o fotografie',
  'A photo from the trip': 'O fotografie din călătorie',
  'A photo just for your portfolio cover.': 'O fotografie doar pentru coperta portofoliului tău.',
  'A photo, or a screenshot from Apple Wallet': 'O fotografie sau o captură din Apple Wallet',
  'A picture, ready for a story.': 'O imagine, gata pentru o poveste.',
  'A pinned video stays first whatever the sort or the filter, and never retires.': 'Un videoclip fixat rămâne primul indiferent de sortare sau filtru și nu dispare niciodată.',
  'A point per video capped at ten, plus 5k / 10k / 50k view milestones.': 'Un punct pe videoclip, maximum zece, plus praguri la 5k / 10k / 50k vizualizări.',
  'A project you\'re working on, a question for the community, something you\'re proud of.': 'Un proiect la care lucrezi, o întrebare pentru comunitate, ceva cu care te mândrești.',
  'A quick check on how getting paid and using vouchers went for you.': 'O verificare rapidă despre cum au mers plățile și voucherele.',
  'A reminder on the Members list when the date comes round. Optional.': 'Un memento în lista de membri când vine data. Opțional.',
  'A running total': 'Un total cumulativ',
  'A sentence or two, please.': 'O propoziție sau două, te rog.',
  'A short walk through the platform, pointing at where everything is. Takes about two minutes and you can stop at any point.': 'O scurtă plimbare prin platformă, care îți arată unde se află fiecare lucru. Durează cam două minute și te poți opri oricând.',
  'A statement already counted this month. Ask the team to take it out.': 'Un extras a contorizat deja luna aceasta. Roagă echipa să îl scoată.',
  'A theme, a brief, hook ideas and a goal for each month. Every VIP in scope is told, sees it at the top of their month, and gets live standings.': 'O temă, un brief, idei de hook și un obiectiv pentru fiecare lună. Toți VIP-ii vizați sunt anunțați, îl văd în capul lunii lor și primesc un clasament în direct.',
  'A travel quote you live by…': 'Un citat despre călătorii după care te ghidezi…',
  'A Tryp.com voucher': 'Un voucher Tryp.com',
  'A video could not be read': 'Un videoclip nu a putut fi citit',
  'A video counts if it is public, posted on your own account during the month it is counted for, and mentions or tags Tryp.com as agreed with the team. Reposts of an earlier video do not count.': 'Un videoclip contează dacă este public, postat pe contul tău în luna pentru care este numărat și menționează sau etichetează Tryp.com așa cum s-a convenit cu echipa. Repostările unui videoclip anterior nu contează.',
  'A video counts if it is public, posted on your own account within the last {days} days, and mentions or tags Tryp.com as agreed with the team. Reposts of an earlier video do not count.': 'Un videoclip contează dacă este public, postat pe contul tău în ultimele {days} zile și menționează sau etichetează Tryp.com conform înțelegerii cu echipa. Repostările unui videoclip anterior nu contează.',
  'A video earns for this many days': 'Un videoclip câștigă atâtea zile',
  'A video that passes several milestones scores every one of them.': 'Un videoclip care trece mai multe praguri punctează la fiecare dintre ele.',
  'A video was disqualified this month': 'Un videoclip a fost descalificat luna aceasta',
