  'A VIP who signs up with the link starts here, until they are approved into a market. Then they move to that market\'s programme on their own.': 'Un VIP care se înscrie cu linkul începe aici, până este aprobat într-o piață. Apoi trece singur în programul acelei piețe.',
  'A voucher reward is created when the statement is approved. You issue the code from Rewards, as with any voucher.': 'La aprobarea extrasului se creează o recompensă de tip voucher. Emiți codul din Recompense, ca pentru orice voucher.',
