  'Approve all {n}': 'Aprobă toate cele {n}',
  'Approve all {n} drafts? Each one is added to the creator\'s balance, and their payout window opens.': 'Aprobi toate cele {n} ciorne? Fiecare se adaugă la soldul creatorului și i se deschide perioada de plată.',
  'Approve all {n} drafts? Each one raises its invoice for the creator. You can still stop an invoice from Rewards.': 'Aprobi toate cele {n} ciorne? Fiecare generează factura creatorului. Poți opri în continuare o factură din Recompense.',
  'Approved': 'Aprobați',
  'Approved, to pay': 'Aprobată, de plătit',
  'Approving a month adds it to each balance. For {d} days after the month ends, a VIP can take cash (from {a}) or a Tryp.com voucher (any amount). Otherwise it keeps growing.': 'Aprobarea unei luni o adaugă la fiecare sold. Timp de {d} zile după încheierea lunii, un VIP poate cere bani (de la {a}) sau un voucher Tryp.com (orice sumă). Altfel, soldul continuă să crească.',
  'Approving a statement adds it to the creator\'s balance and opens their payout window: cash once the balance reaches the threshold, or a Tryp.com voucher for any amount. Their invoice is raised when they ask for cash. Late corrections go on next month\'s statement or as a balance correction in Balances.': 'Aprobarea unui extras îl adaugă la soldul creatorului și deschide perioada de plată: bani când soldul atinge pragul, sau un voucher Tryp.com pentru orice sumă. Factura se emite când cere banii. Corecțiile târzii merg în extrasul lunii următoare sau ca o corecție de sold în Solduri.',
  'Approving a statement raises the creator\'s invoice and counts as approving it. A creator with no payment details is approved anyway and their invoice follows the day they save them. Late corrections go on next month\'s statement, never by reopening a month that is paid.': 'Aprobarea unui extras generează factura creatorului și contează ca aprobare a ei. Un creator fără date de plată este aprobat oricum, iar factura lui urmează în ziua în care le salvează. Corecțiile târzii merg în extrasul lunii următoare, niciodată prin redeschiderea unei luni plătite.',
