  'At the end of each month we take a final reading of your views, draft your statement and, once it is approved, your invoice.': 'La sfârșitul fiecărei luni facem o citire finală a vizualizărilor tale, pregătim extrasul și, după ce este aprobat, factura.',
  'At the end of each month we take a final reading of your views, draft your statement and, once it is approved, your invoice. Small amounts below the minimum payout carry over to the next month.': 'La sfârșitul fiecărei luni facem o ultimă citire a vizualizărilor tale, redactăm extrasul și, după aprobare, factura. Sumele mici sub plata minimă se raportează în luna următoare.',
