  'Bonuses are rules, not hand payments. The month-end close works each one out for every VIP, and you check the result before anything is approved. You can set bonuses for each creator, for the ranking in this market, or for the ranking across every VIP.': 'Bonusurile sunt reguli, nu plăți manuale. Închiderea de la final de lună le calculează pe fiecare pentru fiecare VIP, iar tu verifici rezultatul înainte de aprobare. Poți seta bonusuri pentru fiecare creator, pentru clasamentul din această piață sau pentru clasamentul tuturor VIP.',
  'Bonuses running now': 'Bonusuri active',
  'Booking both in one trip usually comes out cheaper than booking them separately. Show the total per person.': 'Rezervarea ambelor într-o singură călătorie iese de obicei mai ieftin decât separat. Arată totalul de persoană.',
  'Bought, botted or otherwise artificial views mean the videos are removed from your total, and may end your place in the programme.': 'Vizualizările cumpărate, făcute de boți sau artificiale duc la eliminarea videoclipurilor din totalul tău și pot pune capăt locului tău în program.',
