  'Challenge': 'Challenge',
  'Challenge briefs and rules are translated automatically the first time a creator reads them in this language. Check them here, and correct anything that reads wrong. Your version is kept and shown instead.': 'Brieful și regulile challenge-urilor sunt traduse automat prima dată când un creator le citește în această limbă. Verifică-le aici și corectează ce sună greșit. Versiunea ta este păstrată și afișată în loc.',
