  'How this market\'s VIP page looks and what a new VIP is told. Each VIP can also pick their own colour and headline.': 'Cum arată pagina VIP a acestei piețe și ce i se spune unui VIP nou. Fiecare VIP își poate alege și propria culoare și propriul titlu.',
