  'I agree to the {terms} and {privacy}, and to represent Tryp.com honestly in my content.': 'Sunt de acord cu {terms} și cu {privacy} și mă angajez să reprezint Tryp.com cu onestitate în conținutul meu.',
  'I award it': 'Îl acord eu',
  'I can name any capital city in under a second': 'Pot spune orice capitală în mai puțin de o secundă',
  'I don\'t want to take part': 'Nu vreau să particip',
  'I film budget city breaks around my 9 to 5, and when I\'m not travelling I\'m climbing or hunting down the best coffee in town.': 'Filmez city break-uri ieftine în jurul programului de birou, iar când nu călătoresc fie mă cațăr, fie caut cea mai bună cafea din oraș.',
  'I have already added it': 'L-am adăugat deja',
  'I have read the VIP terms and I agree to them.': 'Am citit termenii VIP și sunt de acord cu ei.',
  'I have turned them on': 'Le-am activat',
  'I have turned them on - check again': 'Le-am activat — verifică din nou',
  'I just earned': 'Tocmai am primit',
  'I make short travel videos about the places I go and the things worth stopping for. I am part of the Tryp.com Content Creator Community, where creators from around the world make work for monthly challenges.': 'Fac videoclipuri scurte de călătorie despre locurile în care merg și lucrurile pentru care merită să te oprești. Fac parte din Tryp.com Content Creator Community, unde creatori din toată lumea fac conținut pentru provocări lunare.',
  'I\'ll do this later': 'Fac asta mai târziu',
  'I\'m in Lisbon the same week. Fancy shooting a couple of reels around Alfama, or just a coffee?': 'Sunt în Lisabona în aceeași săptămână. Ai chef să filmăm câteva reels prin Alfama sau măcar o cafea?',
  'I\'m planning a Balkans road trip next spring and would love to team up with anyone heading that way.': 'Plănuiesc un road trip prin Balcani primăvara viitoare și mi-ar plăcea să merg cu cineva care se îndreaptă într-acolo.',
  'Identity': 'Identitate',
  'If an account exists for {email}, you\'ll receive a reset link shortly. Check your spam folder too.': 'Dacă există un cont pentru {email}, vei primi în scurt timp un link de resetare. Verifică și folderul de spam.',
  'If it keeps failing, please let us know rather than waiting.': 'Dacă tot nu merge, anunță-ne în loc să aștepți.',
  'If it still will not read, try the digital pass instead: a screenshot straight from Apple Wallet or the airline app scans far more reliably than a photo of a printed one. Otherwise close this and type the flight in.': 'Dacă tot nu se citește, încearcă varianta digitală: o captură direct din Apple Wallet sau din aplicația companiei se scanează mult mai sigur decât fotografia unei cărți tipărite. Altfel închide asta și scrie zborul manual.',
  'If the month ended now: {n} would earn it, {a} in all.': 'Dacă luna s-ar termina acum: l-ar câștiga {n}, {a} în total.',
  'If you win before we have these, your prize waits until we do. You can add them any time from Settings.': 'Dacă câștigi înainte să avem aceste date, premiul tău așteaptă până le primim. Le poți adăuga oricând din Setări.',
  'If your streak is at risk, we’ll nudge you around 6pm to play before midnight.': 'Dacă seria ta este în pericol, îți dăm un semn pe la ora 18 ca să joci înainte de miezul nopții.',
