  'It appears for everyone who entered, once the challenge has ended - never while it is running.': 'Apare tuturor celor care au participat, după ce provocarea s-a încheiat, niciodată cât timp e în desfășurare.',
  'It behaves like': 'Se comportă ca',
  'It builds up through the period, so being halfway to the goal halfway through is on track.': 'Se acumulează pe parcursul perioadei, deci la jumătatea perioadei să fii la jumătatea obiectivului înseamnă că ești pe drumul cel bun.',
  'It cannot end before it starts.': 'Nu se poate încheia înainte să înceapă.',
  'It goes out of the tracker along with the hook and any notes on it. A synced video comes back on the next sync; one added by hand does not.': 'Iese din tracker împreună cu hook-ul și cu orice notiță. Un videoclip sincronizat revine la următoarea sincronizare; unul adăugat manual nu.',
  'It is a level, not a total, so it is held against the goal itself all the way through.': 'Este un nivel, nu un total, deci este comparat cu obiectivul pe toată perioada.',
