  'Notifications are blocked for this site, so we cannot ask again from here - the browser will not show the prompt twice. Please turn them on and try again.': 'Notificările sunt blocate pentru acest site, așa că nu putem cere din nou de aici — browserul nu afișează solicitarea a doua oară. Activează-le și încearcă din nou.',
  'Notifications are blocked for this site, so we cannot ask from here. Turn them on in your browser or phone settings and they will start working straight away.': 'Notificările sunt blocate pentru acest site, așa că nu putem cere de aici. Activează-le din setările browserului sau ale telefonului și încep să funcționeze imediat.',
