  'On iPhone the app can only be added from Safari. Adding it from Chrome makes a shortcut that opens Chrome again, which is why this screen keeps coming back.': 'Pe iPhone aplicația poate fi adăugată doar din Safari. Dacă o adaugi din Chrome, se creează o scurtătură care deschide iar Chrome, de aceea ecranul acesta tot revine.',
