  'On the current pace this month goes over budget.': 'În ritmul actual, luna aceasta depășește bugetul.',
  'On the current pace this month reaches {p}% of the budget.': 'În ritmul actual, luna aceasta ajunge la {p}% din buget.',
  'On the last day of each month we take a final reading of your views, and your statement appears here once the team has checked it. Your invoice follows.': 'În ultima zi a fiecărei luni facem o ultimă citire a vizualizărilor tale, iar extrasul apare aici după ce echipa îl verifică. Factura urmează.',
  'On the last day of each month we take a final reading of your views. Your statement appears here once the team has checked it, and your invoice follows.': 'În ultima zi a fiecărei luni facem o citire finală a vizualizărilor tale. Extrasul tău apare aici după ce echipa l-a verificat, iar factura urmează.',
