  'Once you connect with other creators they\'ll appear here. Head to a profile or the Connections page to start building your network.': 'După ce te conectezi cu alți creatori, aceștia apar aici. Intră pe un profil sau pe pagina Conexiuni ca să îți construiești rețeaua.',
  'Once you enter a challenge, your videos appear here and on your portfolio automatically.': 'După ce participi la un challenge, videoclipurile tale apar automat aici și în portofoliul tău.',
