  'One a day keeps the streak alive.': 'Unul pe zi ține seria în viață.',
  'One goal comes from {q}': 'Un obiectiv vine din {q}',
  'One goal here is {q}\'s goal shared across its months, rising gently as the quarter goes on.': 'Un obiectiv de aici este obiectivul {q} împărțit pe luni, crescând treptat pe parcursul trimestrului.',
  'One goal here is the monthly goals added together. Set a quarter goal to replace it.': 'Un obiectiv de aici este suma obiectivelor lunare. Setează un obiectiv trimestrial ca să-l înlocuiești.',
  'One goal is the months added up': 'Un obiectiv este suma lunilor',
  'One line per creator per month: name, month, views, and optionally the amount and the rate. Paste straight from a spreadsheet.': 'Un rând pe creator și pe lună: nume, lună, vizualizări și, opțional, suma și tariful. Lipește direct dintr-un tabel.',
  'One line, shown under the market name.': 'Un rând, afișat sub numele pieței.',
  'One link for every VIP, in every market, and it never expires. They sign up as usual, are marked as VIPs in the applications list, and are placed with their own market\'s VIP programme when you approve them.': 'Un singur link pentru toți VIP-urile, în toate piețele, care nu expiră niciodată. Se înscriu ca de obicei, sunt marcați ca VIP în lista de candidaturi și ajung în programul VIP al pieței lor când îi aprobi.',
  'One link for every VIP, in every market. They sign up as usual, are marked as VIPs in the applications list, and are placed with their own market\'s VIP programme when you approve them.': 'Un singur link pentru toți VIP-ii, în toate piețele. Se înscriu ca de obicei, apar marcați ca VIP în lista de cereri și, când îi aprobi, sunt plasați în programul VIP al propriei piețe.',
