  'One moment…': 'Un moment…',
  'One month': 'O lună',
  'One of your {n} VIP videos this month. Post it on your own account, then add the link on your VIP page so its views start counting.': 'Unul dintre cele {n} videoclipuri VIP ale tale din această lună. Publică-l pe contul tău, apoi adaugă linkul pe pagina ta VIP ca vizualizările să înceapă să conteze.',
  'One other market also covers {country}. The team will sort that out with you after you join.': 'Încă o piață acoperă și {country}. Echipa va rezolva asta cu tine după ce te alături.',
  'One puzzle a day': 'Un puzzle pe zi',
  'One rate for every view. Add a step to pay more past a number of views.': 'O singură tarifă pentru toate vizualizările. Adaugă un prag pentru a plăti mai mult peste un anumit număr.',
  'One tap and it is done': 'O apăsare și gata',
  'One thing people should ask you about': 'Un lucru despre care oamenii ar trebui să te întrebe',
  'One travel game a day keeps a run alive - any of the daily puzzles, or any of the practice modes. Miss a day and a freeze covers it, if you have one left.': 'Un joc de călătorii pe zi ține seria în viață — oricare dintre puzzle-urile zilnice sau dintre modurile de antrenament. Dacă ratezi o zi, o acoperă o înghețare, dacă mai ai vreuna.',
