  'Only admins see this preview. Each one uses your name and a sample challenge; open one to check the certificate, the Instagram story and both downloads. Drafts are not given to anybody.': 'Doar administratorii văd această previzualizare. Fiecare folosește numele tău și o provocare exemplu; deschide unul ca să verifici certificatul, povestea de Instagram și ambele descărcări. Ciornele nu se acordă nimănui.',
