  'Only TikTok, Instagram, YouTube and Facebook links carry a view count we can read.': 'Doar linkurile TikTok, Instagram, YouTube și Facebook au un număr de vizualizări pe care îl putem citi.',
  'Only VIP creators and the team can see these. Ask anything, share what is working, and meet the other VIPs.': 'Doar creatorii VIP și echipa le pot vedea. Întreabă orice, împărtășește ce funcționează și cunoaște ceilalți VIP.',
  'Only VIP creators and the team can see these. This is where the WhatsApp group lives now.': 'Doar creatorii VIP și echipa le pot vedea. Aici trăiește acum grupul de WhatsApp.',
