  'Only you can see this.': 'Doar tu vezi asta.',
  'Only you can see this. It rides along in your calendar subscription, so it lands in Apple or Google Calendar with everything else.': 'Doar tu vezi asta. Călătorește odată cu abonamentul tău de calendar, așa că ajunge în Apple sau Google Calendar împreună cu tot restul.',
  'Only you see this. It is how you tell two links apart.': 'Doar tu vezi asta. Așa deosebești două linkuri.',
  'Only you, and the people you add here. Nobody else on the team can see the VIP tools, the payouts or the VIP rooms. Add a market lead for their own programme.': 'Doar tu și persoanele pe care le adaugi aici. Nimeni altcineva din echipă nu vede instrumentele VIP, plățile sau camerele VIP. Adaugă responsabilul unei piețe pentru propriul program.',
