  'Take part in challenges and earn Tryp.com vouchers you can use to book your next trip.': 'Participă la challenge-uri și câștigă vouchere Tryp.com pe care le poți folosi la rezervarea următoarei călătorii.',
  'Take the voucher': 'Ia voucherul',
  'Taken {a}': 'Retras {a}',
