  'Tap "Add to Home screen"': 'Atinge „Adaugă pe ecranul principal”',
  'Tap "Add to Home Screen" and keep "Open as Web App" on': 'Atinge „Adaugă pe ecranul principal” și lasă activat „Deschide ca aplicație web”',
  'Tap "Add to Home Screen", keep "Open as Web App" on, then Add': 'Apasă "Adaugă pe ecranul principal", lasă activ "Deschide ca aplicație web" și apoi Adaugă',
  'Tap "Add to Home Screen", the square with a plus in it': 'Atinge „Adaugă pe ecranul principal”, pătratul cu un plus',
  'Tap "Add" in the top right, then open it from your home screen': 'Atinge „Adaugă” sus în dreapta, apoi deschide aplicația de pe ecranul principal',
  'Tap "Add", then open Tryp.com from the new icon': 'Atinge „Adaugă”, apoi deschide Tryp.com din noua pictogramă',
  'Tap "Install" once more to confirm': 'Atinge „Instalează” încă o dată pentru a confirma',
  'Tap "Open in Safari" below, or paste the address into Safari': 'Atinge „Deschide în Safari” mai jos sau lipește adresa în Safari',
  'Tap "View More", the little arrow pointing down': 'Atinge „Vezi mai multe”, săgeata mică îndreptată în jos',
  'Tap a route, or a country you have landed in': 'Apasă pe o rută sau pe o țară în care ai aterizat',
  'Tap a star': 'Atinge o stea',
  'Tap a star to rate it from 1 to 10. It shapes what we run next.': 'Apasă pe o stea ca să evaluezi de la 1 la 10. Asta ne ajută să decidem ce facem mai departe.',
  'Tap at least one country on your map': 'Atinge cel puțin o țară pe hartă',
  'Tap every country you have been to and watch it glow.': 'Atinge fiecare țară în care ai fost și privește-o cum strălucește.',
  'Tap the country · pinch, scroll or use +/- to zoom · drag to pan · correct stays green, the answer shows in orange': 'Apasă pe țară · apropie degetele, derulează sau folosește +/− pentru zoom · trage ca să muți · răspunsul corect rămâne verde, soluția apare cu portocaliu',
  'Tap the reaction to remove yours': 'Apasă pe reacție ca să o retragi pe a ta',
  'Tap the Share icon, a square with an arrow out of the top': 'Atinge pictograma Partajare, un pătrat cu o săgeată care iese în sus',
