  'We are all in the community. Press a name to open a private chat.': 'Suntem cu toții în comunitate. Apasă pe un nume ca să deschizi o conversație privată.',
  'We are in the community too. Connect or message any of us.': 'Și noi suntem în comunitate. Conectează-te sau scrie-i oricui dintre noi.',
  'We cannot ask again from here once a device has said no.': 'După ce un dispozitiv a spus nu, nu mai putem întreba de aici.',
  'We cannot pay your monthly invoice until they are saved.': 'Nu îți putem plăti factura lunară până nu sunt salvate.',
  'We could not find a free web address for that name. Try a different one in Advanced.': 'Nu am găsit o adresă web liberă pentru acest nume. Încearcă alta la Avansat.',
  'We could not read a preview. Your entry still counts.': 'Nu am putut încărca o previzualizare. Participarea ta contează oricum.',
  'We did not get a session back. That usually means the link was opened twice or it has expired.': 'Nu am primit nicio sesiune înapoi. De obicei înseamnă că linkul a fost deschis de două ori sau a expirat.',
  'We do not recognise that VIP link. Check you copied all of it, or ask the team to send it again. You can still sign up as a creator below.': 'Nu recunoaștem acest link VIP. Verifică dacă l-ai copiat întreg sau cere echipei să ți-l trimită din nou. Te poți înscrie oricum ca creator mai jos.',
  'We email a reset link to the address above.': 'Trimitem pe e-mail un link de resetare la adresa de mai sus.',
  'We filled in what your profile already says. Answer what you like, and your card builds itself as you go.': 'Am completat ce scrie deja în profilul tău. Răspunde la ce vrei, iar cardul tău se construiește din mers.',
  'We filled in what your profile already says. Change anything, skip anything, and your card is ready.': 'Am completat ce scrie deja în profilul tău. Schimbă ce vrei, sari peste ce vrei, și cardul tău e gata.',
  'We have sent you a confirmation link. Open it, then log in and we will take you through the rest.': 'Ți-am trimis un link de confirmare. Deschide-l, autentifică-te și te ghidăm prin restul.',
  'We have your age as {n}. Add your date of birth and it will stay right on your birthday.': 'Avem vârsta ta ca {n}. Adaugă data nașterii și rămâne corectă și de ziua ta.',
  'We post new positions here first. Keep creating great content and you\'ll be top of mind.': 'Posturile noi le anunțăm mai întâi aici. Continuă să faci conținut bun și o să ne gândim primii la tine.',
  'We want your ideas for challenges, features and anything else.': 'Vrem ideile tale pentru provocări, funcții și orice altceva.',
  'We\'re having trouble reaching the server. Your connection might be slow. Give it another try.': 'Avem probleme în a ajunge la server. Poate conexiunea ta e lentă. Mai încearcă o dată.',
