  'You are in an app\'s built-in browser, which cannot add anything to your home screen. Open Tryp.com in Safari or Chrome and this will take ten seconds.': 'Ești în browserul integrat al unei aplicații, care nu poate adăuga nimic pe ecranul principal. Deschide Tryp.com în Safari sau Chrome și durează zece secunde.',
  'You are in the prize places, so this one goes to someone else.': 'Ești pe un loc premiat, așa că acesta merge la altcineva.',
  'You are in the worldwide community as well. A market is where your briefs come from, not a smaller room you go into instead.': 'Ești și în comunitatea mondială. O piață este locul de unde vin briefurile tale, nu o cameră mai mică în care intri în locul ei.',
  'You are in these.': 'Ești în acestea.',
  'You are joining the Tryp.com Content Creator Community, a global community of travel creators who make great content, compete in challenges and earn real rewards.': 'Te alături comunității Tryp.com Content Creator, o comunitate mondială de creatori de călătorii care fac conținut bun, concurează în challenge-uri și câștigă recompense reale.',
  'You are joining the VIP creators': 'Te alături creatorilor VIP',
  'You are left out of the public map, the creators strip and the wall of fame. Fellow creators can still find you in the app.': 'Rămâi în afara hărții publice, a benzii de creatori și a galeriei celor mai buni. Ceilalți creatori te găsesc în continuare în aplicație.',
  'You are looking at {p}. You can see everything here, but only its own lead can change it.': 'Te uiți la {p}. Poți vedea tot, dar doar responsabilul ei poate modifica.',
  'You are looking at this the way the creator sees it. Nothing here can be edited by you.': 'Vezi asta exact cum o vede creatorul. Nu poți edita nimic aici.',
  'You are not on the board yet. Play any travel game today and you will be tomorrow.': 'Încă nu ești pe panou. Joacă azi orice joc de călătorii și mâine ești.',
  'You are paid by the views your videos bring. Add your first video to start your month.': 'Ești plătit după vizualizările pe care le aduc videoclipurile tale. Adaugă primul videoclip ca să-ți începi luna.',
  'You are paid for the views your videos gain during each calendar month, at the rate on your VIP page. Views from before you added a video, or from before the month began, are not counted.': 'Ești plătit pentru vizualizările pe care le câștigă videoclipurile tale în fiecare lună calendaristică, la tariful de pe pagina ta VIP. Vizualizările de dinainte să adaugi un videoclip sau de dinaintea începerii lunii nu se contorizează.',
  'You are reading this the way the creator sees it. Only they can change what it says.': 'Citești asta exact cum o vede creatorul. Doar el poate schimba ce scrie.',
  'You are signed in as': 'Ești conectat ca',
