  'You can set this permanently in Settings.': 'Poți seta asta permanent din Setări.',
  'You could be the first to explore it. Add it to your travels once you go, and the next creator planning this trip will find you here.': 'Ai putea fi primul care o explorează. Adaug-o la călătoriile tale după ce mergi, iar următorul creator care planifică drumul acesta te va găsi aici.',
  'You did not enter this challenge.': 'Nu ai participat la acest challenge.',
